'use strict';
const ORIGIN='https://kingshotdata.kr';
const words={ko:{home:'홈',about:'소개·자료 정책',privacy:'개인정보처리방침',contact:'문의',notice:'게임 자료와 상표의 권리는 각 권리자에게 있습니다. 비공식 팬사이트입니다.',search:'검색',skip:'본문으로 이동'},en:{home:'Home',about:'About & data policy',privacy:'Privacy',contact:'Contact',notice:'Game assets and trademarks belong to their respective owners. This is an unofficial fan site.',search:'Search',skip:'Skip to content'},ja:{home:'ホーム',about:'サイト紹介・資料方針',privacy:'プライバシー',contact:'お問い合わせ',notice:'ゲーム素材と商標の権利は各権利者に帰属します。非公式ファンサイトです。',search:'検索',skip:'本文へ移動'}};
words['zh-tw']={home:'首頁',about:'關於與資料政策',privacy:'隱私權政策',contact:'聯絡我們',notice:'遊戲素材與商標的權利屬於各自權利人。本站為非官方粉絲網站。',search:'搜尋',skip:'跳至主要內容'};
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function route(locale,slug){return '/'+locale+'/'+slug.replace(/^\/+|\/+$/g,'')+'/';}
function page({locale,path,title,description,body,alternates,entityId,extraScripts=[]}){
 if(!words[locale]||!path.startsWith('/'))throw Error('Unsupported static page');
 const w=words[locale],prefix=locale==='ko'?'':'/'+locale,canonical=ORIGIN+path;
 const alt=alternates||Object.fromEntries((locale==='zh-tw'?['ko','en','ja','zh-tw']:['ko','en','ja']).map(l=>[l,path.replace(/^\/(ko|en|ja|zh-tw)\//,'/'+l+'/')]));
 const scripts=['/js/navigation.js?v=ks-ui12-20261012-h1','/js/hub.js?v=ks-ui12-20261012','/js/hub-metrics.js?v=ks-ui9-20261012','/js/my-progress.js?v=ks-ui9-20261012','/js/privacy-controls.js?v=ks-ui12-20261012','/js/design-system.js?v=ks-ui14-20261012','/js/external-data.js?v=ks-ui15-20261012',...extraScripts];
 return '<!doctype html>\n<html lang="'+locale+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><meta name="description" content="'+esc(description)+'"><link rel="canonical" href="'+canonical+'">'+Object.entries(alt).map(([l,p])=>'<link rel="alternate" hreflang="'+esc(l)+'" href="'+ORIGIN+esc(p)+'">').join('')+'<link rel="alternate" hreflang="x-default" href="'+ORIGIN+esc(alt.en||path)+'"><meta property="og:type" content="website"><meta property="og:url" content="'+canonical+'"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(description)+'"><meta property="og:image" content="'+ORIGIN+'/img/kingshotdata-og-v5.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="'+esc(title)+'"><meta name="twitter:description" content="'+esc(description)+'"><link rel="stylesheet" href="/css/design-system.css?v=ks-ui14-20261012"><link rel="stylesheet" href="/css/design-data.css?v=ks-ui14-20261012"><link rel="stylesheet" href="/css/external-data.css?v=ks-ui15-20261012"><link rel="stylesheet" href="/css/my-progress.css?v=2026100621"><script type="application/ld+json">'+JSON.stringify({'@context':'https://schema.org','@type':'WebPage','@id':canonical,url:canonical,name:title,description,inLanguage:locale}).replace(/</g,'\\u003c')+'</script>'+scripts.map(s=>'<script defer src="'+esc(s)+'"></script>').join('')+'</head><body class="ks-design"><a class="kx-skip" href="#content">'+w.skip+'</a><main id="content" class="kx-page" lang="'+locale+'"'+(entityId?' data-entity-id="'+esc(entityId)+'"':'')+'><nav class="kx-breadcrumb" aria-label="Breadcrumb"><a href="'+prefix+'/">'+w.home+'</a><span aria-hidden="true"> / </span><a href="'+prefix+'/#hub-search">'+w.search+'</a></nav>'+body+'</main><footer class="kx-footer"><nav><a href="'+prefix+'/about/">'+w.about+'</a><a href="'+prefix+'/privacy/">'+w.privacy+'</a><a href="'+prefix+'/contact/">'+w.contact+'</a></nav><p>'+w.notice+'</p></footer></body></html>\n';
}
module.exports={page,esc,route,ORIGIN};
